test "aarch64: byte-exact vs LLVM (231 cases)" {
    if (!opts.aarch64) return error.SkipZigTest;
    @setEvalBranchQuota(100_000);
    const m = @import("aarch64/assembler.zig");
    const X = m.X;
    const A = struct {
        const Plain = m.AssemblerT(.{});
        const Checked = m.AssemblerT(.{ .validate = true });
    };
    try check(A, &.{ 0xE0, 0xDD, 0x97, 0xD2 }, "movz", .{ X.x0, @as(u16, 0xBEEF), @as(u6, 0) }, "movz x0, #0xbeef, lsl #0");
    try check(A, &.{ 0x20, 0x00, 0x80, 0xF2 }, "movk", .{ X.x0, @as(u16, 1), @as(u6, 0) }, "movk x0, #1, lsl #0");
    try check(A, &.{ 0xE0, 0xDD, 0xB7, 0xD2 }, "movz", .{ X.x0, @as(u16, 0xBEEF), @as(u6, 16) }, "movz x0, #0xbeef, lsl #16");
    try check(A, &.{ 0x20, 0x00, 0xA0, 0xF2 }, "movk", .{ X.x0, @as(u16, 1), @as(u6, 16) }, "movk x0, #1, lsl #16");
    try check(A, &.{ 0xE0, 0xDD, 0xD7, 0xD2 }, "movz", .{ X.x0, @as(u16, 0xBEEF), @as(u6, 32) }, "movz x0, #0xbeef, lsl #32");
    try check(A, &.{ 0x20, 0x00, 0xC0, 0xF2 }, "movk", .{ X.x0, @as(u16, 1), @as(u6, 32) }, "movk x0, #1, lsl #32");
